import {storefrontCartUnit} from '../utils/storefrontUnits';
import {
  AlertTriangle,
  BadgePercent,
  CheckCircle2,
  ClipboardCheck,
  ClipboardPaste,
  ExternalLink,
  LoaderCircle,
  LockKeyhole,
  LocateFixed,
  MapPin,
  MapPinned,
  PackageCheck,
  ReceiptText,
  ShieldCheck,
  ShoppingBag,
  UserRoundCheck,
  X,
  Banknote,
  Smartphone,
  Save,
  Trash2,
  Truck,
} from 'lucide-react';
import { FormEvent, useEffect, useMemo, useState, useId, useRef, isValidElement, cloneElement, Children } from 'react';
import {useDialogFocus} from '../hooks/useDialogFocus';
import {
  previewGuestPromotionV2,
} from '../services/orders.service';
import { CheckoutRecoveryCoordinator } from '../services/checkoutRecoveryCoordinator';
import { CartItem } from '../types/catalog';
import {
  CheckoutErrors,
  CheckoutField,
  DeliveryZone,
  GuestCheckoutForm,
  GuestOrderReceipt,
  GuestPaymentMethod,
  GuestPromotionQuoteV2,
  PersistedCheckoutAttemptV2,
} from '../types/checkout';
import {
  EMPTY_GUEST_CHECKOUT_FORM,
  buildGoogleMapsUrl,
  buildGuestOrderV2Lines,
  buildWhatsAppOrderMessage,
  buildWhatsAppUrl,
  createPromotionContextKey,
  MAX_GUEST_ORDER_LINE_ITEMS,
  MAX_GUEST_DELIVERY_DETAILS_LENGTH,
  getOrCreateGuestOrderSessionId,
  extractGoogleMapsCoordinates,
  isSupportedGoogleMapsUrl,
  normalizePromotionCode,
  readSavedGuestCustomer,
  saveGuestCustomer,
  clearSavedGuestCustomer,
  saveLastGuestOrder,
  validateGuestCheckout,
} from '../utils/checkout';
import {
  formatCartQuantitySummary,
  calculateCartSubtotal,
} from '../utils/cart';
import { formatJod } from '../utils/money';
import {checkoutErrorMessage} from '../utils/checkoutErrorMessage';
import { CheckoutProgress } from './CheckoutProgress';
import { CheckoutReceiptPanel } from './CheckoutReceiptPanel';
import { TurnstileWidget } from './TurnstileWidget';
import type { TurnstileStatus } from './TurnstileWidget';
import { PublicStorefrontSettings } from '../types/storefront';

interface CheckoutModalProps {
  isOpen: boolean;
  items: CartItem[];
  storeWhatsAppNumber: string;
  storefrontSettings: PublicStorefrontSettings;
  settingsUnavailable: boolean;
  initialPromotionCode?: string;
  coordinator: CheckoutRecoveryCoordinator;
  onClose: () => void;
  onRetryStorefrontSettings: () => void;
  onOpenPrivacyPolicy: () => void;
  onOrderCreated: (
    receipt: GuestOrderReceipt,
    items: CartItem[]
  ) => void;
  onTrackOrder: (receipt: GuestOrderReceipt) => void;
}

const GOVERNORATES = [
  'إربد',
  'المفرق',
  'جرش',
  'عجلون',
  'الزرقاء',
  'عمان',
  'البلقاء',
  'مادبا',
  'الكرك',
  'الطفيلة',
  'معان',
  'العقبة',
];

interface FieldProps {
  label: string;
  required?: boolean;
  error?: string;
  children: React.ReactNode;
}

function Field({ label, required, error, children }: FieldProps) {
  const fieldId = useId();
  const errorId = `${fieldId}-error`;
  let controlId: string | undefined;
  const decorate = (nodes: React.ReactNode): React.ReactNode => Children.map(nodes, child => {
    if (!isValidElement<{id?: string; children?: React.ReactNode; 'aria-describedby'?: string}>(child)) return child;
    if (typeof child.type === 'string' && ['input', 'select', 'textarea'].includes(child.type)) {
      const id = child.props.id || fieldId;
      controlId ||= id;
      return cloneElement(child, {id,
        ...{'aria-required': required || undefined, 'aria-invalid': error ? true : undefined,
          'aria-describedby': [child.props['aria-describedby'], error ? errorId : null].filter(Boolean).join(' ') || undefined},
      });
    }
    return typeof child.type === 'string' && child.props.children
      ? cloneElement(child, {}, decorate(child.props.children)) : child;
  });
  const content = decorate(children);
  return (
    <div className="block">
      <label htmlFor={controlId} className="mb-2 block text-[11px] font-extrabold text-slate-700">
        {label}
        {required && <span className="mr-1 text-rose-500">*</span>}
      </label>
      {content}
      {error && (
        <span id={errorId} role="alert" className="mt-1.5 block text-[10px] font-bold text-rose-600">
          {error}
        </span>
      )}
    </div>
  );
}

const inputClassName =
  'w-full rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm font-bold text-slate-900 outline-none transition placeholder:text-slate-400 focus:border-blue-400 focus:bg-white focus:ring-4 focus:ring-blue-100';

export function CheckoutModal({
  isOpen,
  items,
  storeWhatsAppNumber,
  storefrontSettings,
  settingsUnavailable,
  initialPromotionCode = '',
  coordinator,
  onClose,
  onRetryStorefrontSettings,
  onOpenPrivacyPolicy,
  onOrderCreated,
  onTrackOrder,
}: CheckoutModalProps) {
  const [form, setForm] = useState<GuestCheckoutForm>(
    EMPTY_GUEST_CHECKOUT_FORM
  );
  const [errors, setErrors] = useState<CheckoutErrors>({});
  const focusValidationError = useRef(false);
  const [submitError, setSubmitError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [receipt, setReceipt] = useState<GuestOrderReceipt | null>(null);
  const [submittedItems, setSubmittedItems] = useState<CartItem[]>([]);
  const [isLocating, setIsLocating] = useState(false);
  const [locationMessage, setLocationMessage] = useState('');
  const [showLocationFallback, setShowLocationFallback] = useState(false);
  const [locationMode, setLocationMode] = useState<'current' | 'different'>(
    'current'
  );
  const [isPastingLocation, setIsPastingLocation] = useState(false);
  const [promotionInput, setPromotionInput] = useState('');
  const [promotionQuote, setPromotionQuote] =
    useState<GuestPromotionQuoteV2 | null>(null);
  const [promotionContextKey, setPromotionContextKey] = useState('');
  const [promotionError, setPromotionError] = useState('');
  const [isApplyingPromotion, setIsApplyingPromotion] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<GuestPaymentMethod>('cash_on_delivery');
  const [deliveryZone, setDeliveryZone] = useState<DeliveryZone>('inside_ramtha');
  const [saveCustomerDetails, setSaveCustomerDetails] = useState(false);
  const [isReviewing, setIsReviewing] = useState(false);
  const [turnstileToken, setTurnstileToken] = useState('');
  const [turnstileResetSignal, setTurnstileResetSignal] = useState(0);
  const [turnstileStatus, setTurnstileStatus] = useState<TurnstileStatus>('loading');
  const [pendingAttempt, setPendingAttempt] = useState<PersistedCheckoutAttemptV2 | null>(
    () => {
      const snapshot = coordinator.read();
      return snapshot.attempt.status === 'VALID' ? snapshot.attempt.attempt : null;
    }
  );

  const displayedItems = receipt || pendingAttempt?.serverState === 'UNKNOWN'
    ? submittedItems
    : items;
  const quantitySummary = formatCartQuantitySummary(displayedItems);
  const subtotal = calculateCartSubtotal(displayedItems);
  const currentPromotionContextKey = useMemo(
    () => createPromotionContextKey(form.phone, items),
    [form.phone, items]
  );
  const activePromotionQuote =
    promotionQuote && promotionContextKey === currentPromotionContextKey
      ? promotionQuote
      : null;
  const checkoutBeforeDelivery = pendingAttempt?.serverState === 'UNKNOWN'
    ? (pendingAttempt.request.expectedQuote?.subtotalInMinorUnits ?? subtotal) -
      (pendingAttempt.request.expectedQuote?.discountInMinorUnits ?? 0)
    : activePromotionQuote?.totalInMinorUnits ?? subtotal;
  const selectedDeliveryFee = pendingAttempt?.serverState === 'UNKNOWN'
    ? pendingAttempt.request.expectedQuote?.deliveryFeeInMinorUnits ?? 0
    : deliveryZone === 'inside_ramtha'
      ? storefrontSettings.insideRamthaDeliveryFeeInMinorUnits
      : storefrontSettings.outsideRamthaDeliveryFeeInMinorUnits;
  const checkoutTotal = checkoutBeforeDelivery + selectedDeliveryFee;
  const whatsappUrl = useMemo(() => {
    if (!receipt) return '';
    return buildWhatsAppUrl(
      storeWhatsAppNumber,
      buildWhatsAppOrderMessage({
        receipt,
        items: displayedItems,
        paymentMethod,
      })
    );
  }, [displayedItems, paymentMethod, receipt, storeWhatsAppNumber]);

  useEffect(() => {
    if (!isOpen || receipt) return;
    let active = true;
    void coordinator.resume().then((outcome) => {
      if (!active) return;
      const snapshot = coordinator.read();
      const attempt = snapshot.attempt.status === 'VALID' ? snapshot.attempt.attempt : null;
      setPendingAttempt(attempt);
      if (snapshot.reviewReason) {
        setSubmitError('تحتاج حالة الحفظ المحلية إلى مراجعة قبل إرسال أي طلب جديد.');
        return;
      }
      if (!attempt) return;
      if (attempt.reviewRequired) {
        setSubmitError(attempt.reviewRequired.message);
        return;
      }
      if (attempt.serverState === 'SUCCEEDED' && attempt.receipt) {
        setSubmittedItems(attempt.submittedItems);
        setReceipt(attempt.receipt);
        if (outcome?.status === 'RECONCILED') {
          setSubmitError('');
          onOrderCreated(attempt.receipt, attempt.submittedItems);
        } else {
          setSubmitError(
            outcome?.status === 'BLOCKED_CART'
              ? 'تم تسجيل الطلب، لكن السلة المحفوظة تحتاج معالجة صريحة قبل إكمال تسويتها محليًا.'
              : 'تم تسجيل الطلب، لكن تسوية السلة ما زالت معلقة محليًا. لن يُعاد إرسال الطلب.'
          );
        }
        return;
      }
      if (attempt.serverState === 'UNKNOWN') {
        setForm(attempt.request.customer);
        setPaymentMethod(attempt.request.paymentMethod);
        setDeliveryZone(attempt.request.deliveryZone);
        setPromotionInput(attempt.request.promotionCode || '');
        setSubmittedItems(attempt.submittedItems);
        setIsReviewing(true);
        setSubmitError(
          'حالة محاولة سابقة غير معروفة. أعد التحقق الأمني ثم اضغط «التحقق من نفس الطلب»؛ لن ننشئ مفتاحًا جديدًا.'
        );
      }
    }).catch((error: unknown) => {
      if (!active) return;
      setSubmitError(error instanceof Error ? error.message : 'تعذر استرداد محاولة الطلب بأمان.');
    });
    return () => { active = false; };
  }, [coordinator, isOpen, onOrderCreated, receipt]);

  useEffect(() => {
    if (!isOpen || receipt || pendingAttempt?.serverState === 'UNKNOWN') return;
    const saved = readSavedGuestCustomer(window.localStorage);
    if (saved) {
      setForm(saved);
      setDeliveryZone(
        `${saved.city} ${saved.area}`.includes('الرمثا')
          ? 'inside_ramtha'
          : 'outside_ramtha'
      );
      setSaveCustomerDetails(true);
      setLocationMode(
        saved.latitude !== null && saved.longitude !== null
          ? 'current'
          : saved.googleMapsUrl
            ? 'different'
            : 'current'
      );
    }
  }, [isOpen, pendingAttempt?.serverState, receipt]);

  useEffect(() => {
    if (!settingsUnavailable || receipt) return;
    setIsReviewing(false);
    setTurnstileToken('');
    setSubmitError('تعذر التحقق من إعدادات الطلب والتوصيل. حاول مرة أخرى.');
  }, [receipt, settingsUnavailable]);

  useEffect(() => {
    if (!isOpen || receipt || !initialPromotionCode.trim()) return;
    const normalizedCode = normalizePromotionCode(initialPromotionCode);
    if (!normalizedCode) return;
    setPromotionInput(normalizedCode);
    setPromotionQuote(null);
    setPromotionContextKey('');
    setPromotionError('اضغط «تطبيق» بعد إدخال رقم الهاتف لتثبيت الخصم.');
  }, [initialPromotionCode, isOpen, receipt]);

  useEffect(() => {
    if (
      promotionQuote &&
      promotionContextKey &&
      promotionContextKey !== currentPromotionContextKey
    ) {
      setPromotionQuote(null);
      setPromotionContextKey('');
      setPromotionError(
        'تغير رقم الهاتف أو محتوى السلة؛ أعد تطبيق الرمز لحساب صحيح.'
      );
    }
  }, [
    currentPromotionContextKey,
    promotionContextKey,
    promotionQuote,
  ]);

  const setField = (field: CheckoutField, value: string) => {
    setForm((current) => ({ ...current, [field]: value }));
    setErrors((current) => ({ ...current, [field]: undefined }));
    setSubmitError('');
  };

  const handleMapUrlChange = (value: string) => {
    const coordinates = extractGoogleMapsCoordinates(value);
    setForm((current) => ({
      ...current,
      googleMapsUrl: value,
      latitude: coordinates?.latitude ?? null,
      longitude: coordinates?.longitude ?? null,
    }));
    setErrors((current) => ({
      ...current,
      googleMapsUrl: undefined,
    }));
    setLocationMessage('');
    setShowLocationFallback(false);
    setSubmitError('');
  };

  const handleLocationModeChange = (mode: 'current' | 'different') => {
    setLocationMode(mode);
    setForm((current) => ({
      ...current,
      googleMapsUrl: '',
      latitude: null,
      longitude: null,
    }));
    setErrors((current) => ({
      ...current,
      googleMapsUrl: undefined,
    }));
    setLocationMessage('');
    setShowLocationFallback(false);
    setSubmitError('');
  };

  const handlePasteMapUrl = async () => {
    if (!navigator.clipboard?.readText) {
      setErrors((current) => ({
        ...current,
        googleMapsUrl:
          'الصق رابط خرائط Google يدويًا في الخانة أدناه.',
      }));
      return;
    }

    setIsPastingLocation(true);
    try {
      const value = (await navigator.clipboard.readText()).trim();
      if (!isSupportedGoogleMapsUrl(value)) {
        setErrors((current) => ({
          ...current,
          googleMapsUrl:
            'الحافظة لا تحتوي رابط مشاركة صحيحًا من خرائط Google.',
        }));
        setLocationMessage('');
        return;
      }
      const coordinates = extractGoogleMapsCoordinates(value);
      handleMapUrlChange(value);
      setLocationMessage(
        coordinates
          ? 'تم لصق موقع التوصيل واستخراج الإحداثيات وتأكيدها.'
          : 'تم لصق رابط الموقع. الروابط المختصرة تبقى قابلة للفتح وتحتاج مراجعة الدبوس.'
      );
    } catch {
      setErrors((current) => ({
        ...current,
        googleMapsUrl:
          'تعذر قراءة الحافظة. الصق الرابط يدويًا في الخانة.',
      }));
    } finally {
      setIsPastingLocation(false);
    }
  };

  const handleUseCurrentLocation = () => {
    if (!navigator.geolocation) {
      setErrors((current) => ({
        ...current,
        googleMapsUrl: 'تحديد الموقع غير مدعوم على هذا الجهاز.',
      }));
      setShowLocationFallback(true);
      return;
    }

    setIsLocating(true);
    setLocationMessage('جارٍ تحديد موقعك بدقة...');
    setShowLocationFallback(false);
    setErrors((current) => ({
      ...current,
      googleMapsUrl: undefined,
    }));

    navigator.geolocation.getCurrentPosition(
      ({ coords }) => {
        const latitude = Number(coords.latitude.toFixed(6));
        const longitude = Number(coords.longitude.toFixed(6));
        setForm((current) => ({
          ...current,
          latitude,
          longitude,
          googleMapsUrl: buildGoogleMapsUrl(latitude, longitude),
        }));
        setLocationMode('current');
        setLocationMessage('تم تحديد موقعك وإرفاق رابط الخرائط بالطلب.');
        setShowLocationFallback(false);
        setIsLocating(false);
      },
      (error) => {
        const message =
          error.code === error.PERMISSION_DENIED
            ? 'إذن الموقع مرفوض في هذا المتصفح. فعّله من إعدادات الموقع ثم أعد المحاولة.'
            : error.code === error.TIMEOUT
            ? 'استغرق تحديد الموقع وقتًا طويلًا. حاول مرة أخرى.'
            : 'تعذر تحديد الموقع الحالي. ألصق رابط الخرائط يدويًا.';
        setErrors((current) => ({
          ...current,
          googleMapsUrl: message,
        }));
        setLocationMessage('');
        setShowLocationFallback(true);
        setIsLocating(false);
      },
      {
        enableHighAccuracy: true,
        timeout: 15000,
        maximumAge: 60000,
      }
    );
  };

  const handlePromotionChange = (value: string) => {
    setPromotionInput(value.toUpperCase());
    setPromotionQuote(null);
    setPromotionError('');
    setSubmitError('');
  };

  const handleApplyPromotion = async () => {
    const code = normalizePromotionCode(promotionInput);
    if (!/^[A-Z0-9_-]{3,32}$/.test(code)) {
      setPromotionError('اكتب رمزًا صحيحًا ثم اضغط تطبيق.');
      return;
    }

    setIsApplyingPromotion(true);
    setPromotionError('');
    try {
      const quote = await previewGuestPromotionV2(
        buildGuestOrderV2Lines(items),
        code,
        form.phone
      );
      setPromotionInput(quote.code);
      setPromotionQuote(quote);
      setPromotionContextKey(currentPromotionContextKey);
    } catch (error) {
      setPromotionQuote(null);
      setPromotionError(
        error instanceof Error
          ? error.message
          : 'تعذر التحقق من رمز الخصم.'
      );
    } finally {
      setIsApplyingPromotion(false);
    }
  };

  const handleRemovePromotion = () => {
    setPromotionInput('');
    setPromotionQuote(null);
    setPromotionContextKey('');
    setPromotionError('');
  };

  const validateForReview = () => {
    setSubmitError('');
    if (isSubmitting || receipt) return;
    if (settingsUnavailable) {
      setSubmitError('تعذر التحقق من إعدادات الطلب والتوصيل. حاول مرة أخرى.');
      return false;
    }
    if (items.length === 0) {
      setSubmitError('السلة فارغة. أضف صنفًا قبل إرسال الطلب.');
      return false;
    }

    if (items.length > MAX_GUEST_ORDER_LINE_ITEMS) {
      setSubmitError(
        `الحد الأقصى للطلب هو ${MAX_GUEST_ORDER_LINE_ITEMS} صنفًا. احذف ${items.length - MAX_GUEST_ORDER_LINE_ITEMS} صنفًا على الأقل ثم حاول مرة أخرى.`
      );
      return false;
    }

    if (!storefrontSettings.ordersEnabled) {
      setSubmitError('الطلبات متوقفة مؤقتًا من إدارة المتجر. يمكنك التواصل معنا عبر واتساب.');
      return false;
    }

    if (subtotal < storefrontSettings.minimumOrderInMinorUnits) {
      setSubmitError(`الحد الأدنى للطلب هو ${formatJod(storefrontSettings.minimumOrderInMinorUnits)}. أضف أصنافًا أخرى للمتابعة.`);
      return false;
    }

    if (normalizePromotionCode(promotionInput) && !activePromotionQuote) {
      setPromotionError('اضغط «تطبيق» للتحقق من الرمز قبل إرسال الطلب.');
      return false;
    }

    const validationErrors = validateGuestCheckout(form);
    if (Object.keys(validationErrors).length > 0) {
      focusValidationError.current = true;
      setErrors(validationErrors);
      setSubmitError('راجع الحقول المطلوبة قبل إرسال الطلب.');
      return false;
    }

    if (
      deliveryZone === 'inside_ramtha' &&
      !`${form.governorate} ${form.city} ${form.area}`.includes('الرمثا')
    ) {
      focusValidationError.current = true;
      setErrors((current) => ({
        ...current,
        city: 'اكتب الرمثا أو اختر «خارج الرمثا» لحساب أجرة التوصيل الصحيحة.',
      }));
      setSubmitError('منطقة التوصيل لا تتطابق مع المدينة المدخلة.');
      return false;
    }

    return true;
  };

  const handleReview = (event: FormEvent) => {
    event.preventDefault();
    if (!validateForReview()) return;
    setIsReviewing(true);
  };

  const handleSubmit = async () => {
    const recoveryAttempt = pendingAttempt?.serverState === 'UNKNOWN' ? pendingAttempt : null;
    if (!recoveryAttempt && !validateForReview()) return;
    if (!turnstileToken) {
      setSubmitError('أكمل التحقق الأمني قبل إرسال الطلب.');
      return;
    }

    setIsSubmitting(true);
    setSubmitError('');
    let attempt: PersistedCheckoutAttemptV2 | null = recoveryAttempt;
    try {
      if (!attempt) {
        const lines = buildGuestOrderV2Lines(items);
        const authoritativeQuote = await previewGuestPromotionV2(
          lines,
          activePromotionQuote?.code,
          form.phone
        );
        const request = {
          contractVersion: 'phase3-customer-reservation-v2' as const,
          idempotencyKey: crypto.randomUUID(),
          clientSessionId: getOrCreateGuestOrderSessionId(window.sessionStorage),
          customer: structuredClone(form),
          items: lines,
          promotionCode: authoritativeQuote.code || undefined,
          paymentMethod,
          deliveryZone,
          expectedQuote: {
            subtotalInMinorUnits: authoritativeQuote.subtotalInMinorUnits,
            discountInMinorUnits: authoritativeQuote.discountInMinorUnits,
            deliveryFeeInMinorUnits: selectedDeliveryFee,
            totalInMinorUnits: authoritativeQuote.totalInMinorUnits + selectedDeliveryFee,
          },
        };
        attempt = await coordinator.prepare(request, items);
        setPendingAttempt(attempt);
      }
      const outcome = await coordinator.submit(attempt.attemptId, turnstileToken);
      const latest = coordinator.read();
      const latestAttempt = latest.attempt.status === 'VALID' ? latest.attempt.attempt : null;
      setPendingAttempt(latestAttempt);
      const result = 'receipt' in outcome ? outcome.receipt : undefined;
      if (result) {
        try {
          if (saveCustomerDetails) saveGuestCustomer(window.localStorage, form);
          else clearSavedGuestCustomer(window.localStorage);
          saveLastGuestOrder(
            window.localStorage,
            result.orderNumber,
            attempt.submittedItems
          );
        } catch {
          // Durable server-success evidence remains authoritative.
        }
        setSubmittedItems(attempt.submittedItems);
        setReceipt(result);
        if (outcome.status === 'RECONCILED') {
          onOrderCreated(result, attempt.submittedItems);
          setSubmitError('');
        } else {
          setSubmitError(
            outcome.status === 'BLOCKED_CART'
              ? 'تم تسجيل الطلب، لكن السلة المحفوظة تحتاج معالجة صريحة قبل إكمال تسويتها محليًا.'
              : outcome.status === 'SERVER_SUCCESS_MEMORY_ONLY'
                ? outcome.message
                : 'تم تسجيل الطلب، لكن تسوية السلة ما زالت معلقة محليًا. لن يُعاد إرسال الطلب.'
          );
        }

        const popup = window.open(
          buildWhatsAppUrl(
            storeWhatsAppNumber,
            buildWhatsAppOrderMessage({
              receipt: result,
              items: attempt.submittedItems,
              paymentMethod: attempt.request.paymentMethod,
            })
          ),
          '_blank',
          'noopener,noreferrer'
        );
        if (popup) popup.opener = null;
        return;
      }
      setTurnstileToken('');
      setTurnstileResetSignal((current) => current + 1);
      setSubmitError(
        outcome.status === 'UNKNOWN' || outcome.status === 'REJECTED'
          ? outcome.message
          : 'تحتاج محاولة الطلب إلى مراجعة قبل المتابعة.'
      );
    } catch (error) {
      const latest = coordinator.read();
      setPendingAttempt(latest.attempt.status === 'VALID' ? latest.attempt.attempt : null);
      setTurnstileToken('');
      setTurnstileResetSignal((current) => current + 1);
      setSubmitError(
        error instanceof Error
          ? error.message
