 * @param {{readProjects?:()=>Promise<object[]>,confirmTarget?:()=>Promise<void>,readPassword?:()=>Promise<string>,executor?:(connection:string[],env:NodeJS.ProcessEnv)=>{command:string,args:string[],env?:NodeJS.ProcessEnv}} [io]
