import { supabase, isSupabaseConfigured } from '../../lib/supabase';
import {
  CrmCustomer,
  CrmCustomerAddress,
  CrmCustomerFilterParams,
  CrmCustomerOrderSummary,
  CrmCustomerResponse,
  CrmCustomerStats,
  CustomerTag,
} from '../../types/crm';

type RawCustomer = Record<string, any>;

function mapAddress(address: Record<string, any>): CrmCustomerAddress {
  const latitude =
    address.latitude === null || address.latitude === undefined
      ? undefined
      : Number(address.latitude);
  const longitude =
    address.longitude === null || address.longitude === undefined
      ? undefined
      : Number(address.longitude);
  const hasCoordinates =
    Number.isFinite(latitude) && Number.isFinite(longitude);

  return {
    id: address.id,
    customerId: address.customer_id,
    governorate: address.governorate || '',
    city: address.city || '',
    area: address.area || '',
    street: address.street || '',
    building: address.building || undefined,
    floor: address.floor || undefined,
    apartment: address.apartment || undefined,
    notes: address.notes || undefined,
    latitude: hasCoordinates ? latitude : undefined,
    longitude: hasCoordinates ? longitude : undefined,
    formattedAddress: address.formatted_address || undefined,
    googleMapsUrl: address.google_maps_url || undefined,
    locationSource: address.location_source || 'manual',
    locationConfirmed: Boolean(address.location_confirmed),
    isDefault: Boolean(address.is_default),
    createdAt: address.created_at,
  };
}

function deriveCustomerStatus(customer: RawCustomer) {
  const isBlocked = Boolean(customer.is_blocked);
  const isActive = customer.is_active !== false && !isBlocked;
  const isVip = Boolean(customer.is_vip);

  return {
    isBlocked,
    isActive,
    isVip,
    status: isBlocked
      ? ('blocked' as const)
      : isVip
      ? ('vip' as const)
      : isActive
      ? ('active' as const)
      : ('inactive' as const),
  };
}

function deriveCustomerTags(
  customer: RawCustomer,
  totalSpending: number
): CustomerTag[] {
  const tags: CustomerTag[] = [];
  if (customer.is_vip || totalSpending >= 500) tags.push('VIP');
  tags.push(customer.customer_type === 'wholesale' ? 'Wholesale' : 'Retail');

  const createdAt = new Date(customer.created_at || 0).getTime();
  if (createdAt && Date.now() - createdAt < 30 * 24 * 60 * 60 * 1000) {
    tags.push('New Customer');
  }
  return tags;
}

function textValue(value: unknown, fallback = ''): string {
  return typeof value === 'string' ? value : fallback;
}

function numberValue(value: unknown): number {
  const numericValue = Number(value);
  return Number.isFinite(numericValue) ? numericValue : 0;
}

function mapCrmDirectoryCustomer(row: Record<string, unknown>): CrmCustomer {
  const totalSpending = numberValue(row.total_spending_in_minor_units) / 1000;
  const currentBalance = numberValue(row.current_balance_in_minor_units) / 1000;
  const customer = {
    id: textValue(row.id),
    full_name: textValue(row.full_name, 'عميل بدون اسم'),
    phone: textValue(row.phone),
    email: textValue(row.email),
    whatsapp: textValue(row.whatsapp),
    governorate: textValue(row.governorate),
    notes: textValue(row.notes),
    customer_type: textValue(row.customer_type, 'retail'),
    is_active: row.is_active !== false,
    is_vip: row.is_vip === true,
    is_blocked: row.is_blocked === true,
    is_deleted: row.is_deleted === true,
    credit_limit_in_minor_units: numberValue(row.credit_limit_in_minor_units),
    created_at: textValue(row.created_at),
    updated_at: textValue(row.updated_at),
  } as RawCustomer;
  const state = deriveCustomerStatus(customer);

  return {
    id: customer.id,
    fullName: customer.full_name,
    phone: customer.phone,
    email: customer.email,
    governorate:
      textValue(row.address_governorate) || customer.governorate || 'غير محدد',
    ...state,
    isDeleted: false,
    tags: deriveCustomerTags(customer, totalSpending),
    notes: customer.notes,
    whatsapp: customer.whatsapp || customer.phone || undefined,
    creditLimit: customer.credit_limit_in_minor_units / 1000,
    currentBalance: Number(currentBalance.toFixed(3)),
    customerType:
      customer.customer_type === 'wholesale' ? 'wholesale' : 'retail',
    createdAt: customer.created_at,
    updatedAt: customer.updated_at,
    totalOrdersCount: Math.max(0, Math.floor(numberValue(row.total_orders_count))),
    totalSpending: Number(totalSpending.toFixed(3)),
  };
}

export async function fetchCustomersCrmFromSupabase(
  params: CrmCustomerFilterParams
): Promise<CrmCustomerResponse> {
  const page = params.page && params.page > 0 ? params.page : 1;
  const pageSize =
    params.pageSize && params.pageSize > 0 ? params.pageSize : 10;
  const statusFilter = params.statusFilter || 'all';
  const sortBy = params.sortBy || 'latest';

  const failure = (error: string): CrmCustomerResponse => ({
    success: false,
    customers: [],
    totalCount: 0,
    page,
    pageSize,
    totalPages: 0,
    error,
  });

  if (!isSupabaseConfigured || !supabase) {
    return failure('لم يتم إعداد الاتصال بقاعدة بيانات Supabase بنجاح.');
  }

  try {
    const { data, error } = await supabase.rpc('get_crm_customer_page', {
      p_page: page,
      p_page_size: Math.min(pageSize, 100),
      p_search: params.searchQuery?.trim() || null,
      p_status: statusFilter,
      p_sort: sortBy,
    });
    if (error) return failure(error.message);

    const payload =
      data && typeof data === 'object'
        ? (data as Record<string, unknown>)
        : {};
    const rows = Array.isArray(payload.customers) ? payload.customers : [];
    const customers = rows
      .filter(
        (row): row is Record<string, unknown> =>
          Boolean(row) && typeof row === 'object'
      )
      .map(mapCrmDirectoryCustomer);
    const totalCount = Math.max(0, Math.floor(numberValue(payload.total_count)));
    const totalPages = Math.max(Math.ceil(totalCount / pageSize), 1);

    return {
      success: true,
      customers,
      totalCount,
      page,
      pageSize,
      totalPages,
    };
  } catch (error: unknown) {
    return failure(
      error instanceof Error ? error.message : 'تعذر جلب بيانات العملاء.'
    );
  }
}

export async function fetchCustomerDetailsCrmFromSupabase(
  customerId: string,
  params?: { historyPage?: number; historyPageSize?: number }
): Promise<{ success: boolean; customer: CrmCustomer | null; error?: string }> {
  if (!isSupabaseConfigured || !supabase) {
    return { success: false, customer: null, error: 'Supabase غير مهيأ.' };
  }

  try {
    const historyPage = Math.max(1, Math.trunc(params?.historyPage || 1));
    const historyPageSize = Math.min(
      100,
      Math.max(1, Math.trunc(params?.historyPageSize || 25))
    );
    const { data, error } = await supabase.rpc(
      'get_crm_customer_detail_page',
      {
        p_customer_id: customerId,
        p_history_page: historyPage,
        p_history_page_size: historyPageSize,
      }
    );

    if (error || !data || typeof data !== 'object') {
      return {
        success: false,
        customer: null,
        error: error?.message || 'العميل غير موجود.',
      };
    }

    const payload = data as Record<string, unknown>;
    const customerRow = payload.customer && typeof payload.customer === 'object'
      ? payload.customer as Record<string, unknown>
      : null;
    if (!customerRow) {
      return { success: false, customer: null, error: 'العميل غير موجود.' };
    }
    const addresses = (Array.isArray(payload.addresses) ? payload.addresses : [])
      .filter(
        (address): address is Record<string, unknown> =>
          Boolean(address) && typeof address === 'object'
      )
      .map(mapAddress);
    const statsRow = payload.stats && typeof payload.stats === 'object'
      ? payload.stats as Record<string, unknown>
      : {};
    const totalSpending = numberValue(
      statsRow.total_spending_in_minor_units
    ) / 1000;
    const outstandingBalance = numberValue(
      statsRow.outstanding_in_minor_units
    ) / 1000;
    const state = deriveCustomerStatus(customerRow);
    const orderHistory: CrmCustomerOrderSummary[] = (
      Array.isArray(payload.orders) ? payload.orders : []
    ).filter(
      (order): order is Record<string, unknown> =>
        Boolean(order) && typeof order === 'object'
    ).map((order) => {
      return {
        id: textValue(order.id),
        orderNumber: textValue(order.order_number),
        status: textValue(order.status),
        totalAmount: numberValue(order.total_in_minor_units) / 1000,
        amountPaid: numberValue(order.amount_paid_in_minor_units) / 1000,
        amountDue: numberValue(order.amount_due_in_minor_units) / 1000,
        paymentStatus: ['paid', 'partially_paid'].includes(
          textValue(order.payment_status)
        )
          ? textValue(order.payment_status) as 'paid' | 'partially_paid'
          : 'unpaid',
        source: textValue(order.source, 'website'),
        itemsCount: Math.max(0, Math.trunc(numberValue(order.items_count))),
        createdAt: textValue(order.created_at),
      };
    });
    const stats: CrmCustomerStats = {
      totalOrders: Math.max(0, Math.trunc(numberValue(statsRow.total_orders))),
      completedOrders: Math.max(
        0,
        Math.trunc(numberValue(statsRow.completed_orders))
      ),
      cancelledOrders: Math.max(
        0,
        Math.trunc(numberValue(statsRow.cancelled_orders))
      ),
      totalSpending: Number(totalSpending.toFixed(3)),
      outstandingBalance: Number(outstandingBalance.toFixed(3)),
      averageOrderValue: Number(
        (numberValue(statsRow.average_order_value_in_minor_units) / 1000).toFixed(3)
      ),
      lastOrderDate: textValue(statsRow.last_order_date) || null,
    };
    const customer: CrmCustomer = {
      id: textValue(customerRow.id),
      fullName: textValue(customerRow.full_name, 'عميل بدون اسم'),
      phone: textValue(customerRow.phone),
      email: textValue(customerRow.email),
      governorate:
        textValue(customerRow.governorate) ||
        addresses[0]?.governorate ||
        'غير محدد',
      ...state,
      isDeleted: customerRow.is_deleted === true,
      tags: deriveCustomerTags(customerRow, totalSpending),
      notes: textValue(customerRow.notes),
      whatsapp:
        textValue(customerRow.whatsapp) || textValue(customerRow.phone) || undefined,
      creditLimit: numberValue(customerRow.credit_limit_in_minor_units) / 1000,
      currentBalance: stats.outstandingBalance,
      customerType:
        textValue(customerRow.customer_type) === 'wholesale'
          ? 'wholesale'
          : 'retail',
      createdAt: textValue(customerRow.created_at),
      updatedAt: textValue(customerRow.updated_at) || undefined,
      totalOrdersCount: stats.totalOrders,
      totalSpending: stats.totalSpending,
      addresses,
      stats,
      orderHistory,
      orderHistoryPage: Math.max(
        1,
        Math.trunc(numberValue(payload.history_page) || historyPage)
      ),
      orderHistoryPageSize: Math.max(
        1,
        Math.trunc(numberValue(payload.history_page_size) || historyPageSize)
      ),
      orderHistoryTotalCount: Math.max(
        0,
        Math.trunc(numberValue(payload.history_total_count))
      ),
      orderHistoryHasMore: payload.history_has_more === true,
    };

    return { success: true, customer };
  } catch (error: unknown) {
    return {
      success: false,
      customer: null,
      error:
        error instanceof Error ? error.message : 'تعذر جلب ملف العميل.',
    };
  }
}

export interface SaveCustomerInput {
  fullName: string;
  phone: string;
  email?: string;
  governorate?: string;
  whatsapp?: string;
  notes?: string;
  customerType?: 'retail' | 'wholesale';
}

async function saveCustomerThroughRpc(
  input: SaveCustomerInput,
  customerId?: string
): Promise<{ success: boolean; customerId?: string; error?: string }> {
  if (!isSupabaseConfigured || !supabase) {
    return { success: false, error: 'Supabase غير مهيأ.' };
  }

  try {
    const { data, error } = await supabase.rpc('save_customer', {
      p_full_name: input.fullName,
      p_phone: input.phone,
      p_customer_id: customerId || null,
      p_email: input.email || null,
      p_governorate: input.governorate || null,
      p_whatsapp: input.whatsapp || null,
      p_notes: input.notes || null,
      p_customer_type: input.customerType || 'retail',
    });
    if (error) return { success: false, error: error.message };
    return {
      success: true,
      customerId: data?.customer_id || customerId,
    };
  } catch (error: any) {
    return {
      success: false,
      error: error?.message || 'تعذر حفظ بيانات العميل.',
    };
  }
}

export function createCustomerCrmInSupabase(input: SaveCustomerInput) {
  return saveCustomerThroughRpc(input);
}

export async function updateCustomerCrmInSupabase(
  customerId: string,
  updates: SaveCustomerInput
) {
  return saveCustomerThroughRpc(updates, customerId);
}

async function setCustomerStatus(
  customerId: string,
  action: 'block' | 'unblock' | 'delete'
): Promise<{ success: boolean; error?: string }> {
  if (!isSupabaseConfigured || !supabase) {
    return { success: false, error: 'Supabase غير مهيأ.' };
  }

  try {
    const { error } = await supabase.rpc('set_customer_status', {
      p_customer_id: customerId,
      p_action: action,
    });
    return error
      ? { success: false, error: error.message }
      : { success: true };
  } catch (error: any) {
    return {
      success: false,
      error: error?.message || 'تعذر تعديل حالة العميل.',
    };
  }
}

export function toggleCustomerBlockStatusInSupabase(
  customerId: string,
  isBlocked: boolean
) {
  return setCustomerStatus(customerId, isBlocked ? 'block' : 'unblock');
}

export function softDeleteCustomerInSupabase(customerId: string) {
