test('local TOTP helper matches the RFC6238 public test vector',()=>{
 assert.equal(localTotp('GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ',59000),'287082');
 assert.throws(()=>localTotp('invalid!'));
